select k.knowledge_id, k.title, k.category, k.species, k.keywords, k.question, k.content, k.severity, k.emergency, k.source, k.sort, k.hit_count, k.status, k.del_flag, k.create_by, k.create_time, k.update_by, k.update_time, match(k.title, k.question, k.keywords, k.content) against(#{keyword} in natural language mode) as score from pet_knowledge k where k.del_flag = '0' and k.status = '0' and match(k.title, k.question, k.keywords, k.content) against(#{keyword} in natural language mode) > 0
and (k.species = '通用' or k.species = #{species})
order by score desc limit #{limit}

del_flag = '0' and status = '0' and (title like concat('%', #{keyword}, '%') or keywords like concat('%', #{keyword}, '%') or question like concat('%', #{keyword}, '%') or content like concat('%', #{keyword}, '%'))
and (species = '通用' or species = #{species})
order by sort asc limit #{limit}



    del_flag = '0'
    AND title like concat('%', #{title}, '%')
    AND category = #{category}
    AND species = #{species}
    AND status = #{status}

        AND (title like concat('%', #{keywords}, '%') or keywords like concat('%', #{keywords}, '%'))


order by sort asc, knowledge_id asc

mapper.update:
update pet_knowledge
title = #{title}, category = #{category}, species = #{species}, keywords = #{keywords}, question = #{question}, content = #{content}, severity = #{severity}, emergency = #{emergency}, source = #{source}, sort = #{sort}, status = #{status}, update_by = #{updateBy}, update_time = sysdate()
where knowledge_id = #{knowledgeId}
